@Composable
fun Feed(state: FeedUiState, onClick: (String) -> Unit) {
    LazyColumn(
        contentPadding = PaddingValues(vertical = 12.dp),
        verticalArrangement = Arrangement.spacedBy(8.dp),
    ) {
        item(key = "header", contentType = "header") { FeedHeader() }

        items(
            items = state.items,
            key = { it.id },                 // stable identity
            contentType = { it.kind },       // slot reuse by shape
        ) { post ->
            PostRow(
                post = post,
                onClick = onClick,           // auto-memoized under strong skipping
                modifier = Modifier.animateItem(),
            )
        }

        if (state.isLoadingMore) {
            item(key = "loading", contentType = "loading") { LoadingRow() }
        }
    }
}

@Composable
private fun PostRow(post: Post, onClick: (String) -> Unit, modifier: Modifier = Modifier) {
    Row(modifier.clickable { onClick(post.id) }) {
        AsyncImage(
            model = post.thumbnailUrl,
            contentDescription = null,
            modifier = Modifier.size(64.dp),   // fixed size — no reflow when it loads
        )
        Text(post.title)
    }
}

// 1. Simple: one value, spring spec so it's interruptible
@Composable
fun ExpandableCard(expanded: Boolean) {
    val elevation by animateDpAsState(
        targetValue = if (expanded) 8.dp else 1.dp,
        animationSpec = spring(dampingRatio = Spring.DampingRatioMediumBouncy),
        label = "elevation",
    )
    Card(elevation = CardDefaults.cardElevation(elevation)) { /* … */ }
}

// 2. Several values from one state
@Composable
fun SelectableChip(selected: Boolean) {
    val transition = updateTransition(selected, label = "chip")
    val bg by transition.animateColor(label = "bg") { if (it) Primary else Surface }
    val scale by transition.animateFloat(label = "scale") { if (it) 1.05f else 1f }

    Box(
        Modifier
            .graphicsLayer { scaleX = scale; scaleY = scale }   // draw-phase read
            .background(bg)
    )
}

// 3. Gesture-driven: needs Animatable
@Composable
fun SwipeToDismiss(onDismiss: () -> Unit) {
    val offsetX = remember { Animatable(0f) }
    val scope = rememberCoroutineScope()

    Box(
        Modifier
            .offset { IntOffset(offsetX.value.roundToInt(), 0) }   // layout-phase read
            .pointerInput(Unit) {
                detectHorizontalDragGestures(
                    onHorizontalDrag = { _, delta ->
                        scope.launch { offsetX.snapTo(offsetX.value + delta) }
                    },
                    onDragEnd = {
                        scope.launch {
                            if (abs(offsetX.value) > 300f) { offsetX.animateTo(1000f); onDismiss() }
                            else offsetX.animateTo(0f)              // spring back
                        }
                    },
                )
            }
    )
}

@Composable
fun FavoriteToggle(isFavorite: Boolean, onToggle: (Boolean) -> Unit) {
    Icon(
        imageVector = if (isFavorite) Icons.Filled.Favorite else Icons.Outlined.FavoriteBorder,
        contentDescription = null,          // description lives on the toggleable wrapper
        modifier = Modifier
            .minimumInteractiveComponentSize()          // >= 48dp target
            .toggleable(
                value = isFavorite,
                onValueChange = onToggle,
                role = Role.Switch,                      // announces the control type
            )
            .semantics {
                contentDescription = "Favorite"
                stateDescription = if (isFavorite) "On" else "Off"
            }
    )
}

// A View that needs lifecycle forwarding
@Composable
fun Map(modifier: Modifier = Modifier) {
    val lifecycleOwner = LocalLifecycleOwner.current
    val mapView = remember { MapView(/* context */) }

    DisposableEffect(lifecycleOwner) {
        val observer = LifecycleEventObserver { _, event ->
            when (event) {
                Lifecycle.Event.ON_START -> mapView.onStart()
                Lifecycle.Event.ON_STOP -> mapView.onStop()
                else -> Unit
            }
        }
        lifecycleOwner.lifecycle.addObserver(observer)
        onDispose { lifecycleOwner.lifecycle.removeObserver(observer) }
    }

    AndroidView(factory = { mapView }, modifier = modifier, onRelease = { it.onDestroy() })
}
